INSERT INTO policies (policy_no, title, description, category, min_age, max_age, application_end_date, support_content, additional_qualification, application_method, submission_documents, screening_method, participation_restriction, application_url) VALUES
('MOCK-P001', '청년 디지털 일자리 지원 사업', 'IT 분야 실무 경험과 교육을 제공하고 취업 연계를 지원하는 고용노동부 주관 사업입니다.', '일자리', 19, 34, '2025-06-30', '청년 채용 기업에 인건비 월 최대 190만원 지원 및 실무 교육 제공', '만 19세 이상 34세 이하의 미취업 청년', '워크넷 청년일자리사업 페이지에서 온라인 접수', '이력서, 자기소개서, 최종학력 졸업(예정)증명서', NULL, '동일 사업 참여 이력이 있는 기업은 재신청 불가', 'https://www.work.go.kr'),
('MOCK-P002', '청년 월세 한시 특별지원', '서울 및 전국 무주택 청년의 주거비 부담 경감을 위해 실제 납부하는 월세를 지원합니다.', '주거', 19, 34, '2025-06-30', '실제 납부하는 월세 범위 내에서 월 최대 20만원까지 최장 12개월 분할 지원', '부모와 별도 거주하는 무주택 청년 중 소득 기준 충족자', '복지로 온라인 신청 또는 주소지 관할 행정복지센터 방문 신청', '임대차계약서, 통장사본, 소득금액증명원', '서류 요건 충족 여부 행정 확인 후 순차 지급', '주택 소유자, 다른 월세 지원사업 중복 수급자는 제외', 'https://www.bokjiro.go.kr'),
('MOCK-P003', 'K-디지털 트레이닝 (국비지원)', '디지털, AI, 신기술 핵심 실무 중심 교육을 통해 고소득 기술 취업 역량을 극대화하는 과정입니다.', '교육', 19, 34, '2025-07-15', '수강료 전액 지원(국비무료) 및 월 최대 31만 6천원의 훈련장려금 지급', '만 19세~34세 대학 졸업(예정)자 및 미취업 청년, 공학계열 전공자 한정', 'HRD-Net에서 과정 검색 후 온라인 수강 신청', '수강신청서, 재직·졸업증명서, 훈련장려금 지급 계좌 사본', '선착순 접수 및 과정별 사전 상담 통과자 선발', NULL, 'https://www.hrd.go.kr'),
('MOCK-P004', '청년내일채움공제', '중소기업 취업 청년의 자산 형성을 지원하여 장기 근속을 유도하고 대기업과의 격차를 완화합니다.', '일자리', 15, 34, '2025-08-31', '청년이 2년간 300만원을 적립하면 정부와 기업이 적립해 총 1,200만원 자산 마련', '5인 이상 중소기업에 신규 취업한 청년 및 해당 기업', '청년내일채움공제 홈페이지에서 청약 신청', '취업사실확인서, 4대보험 가입내역확인서, 기업 사업자등록증 사본', NULL, '동일 사업장에서 과거 청약 후 중도해지한 이력이 있으면 재가입 제한', 'https://www.sbcof.or.kr'),
('MOCK-P005', '청년 주거급여 분리지급', '주거급여 수급 가구 중 학업이나 취업으로 부모와 타 지역에 거주하는 청년에게 별도로 급여를 지급합니다.', '주거', 19, 30, '2025-12-31', '부모와 떨어진 별도 가구원에 대해 서울 및 해당 지역 기준 임차료 지급', '주거급여 수급 가구원 중 만 19세 이상 30세 미만 미혼 자녀', '주민등록상 부모 거주지 읍면동 행정복지센터 방문 혹은 복지로 온라인 신청', '임대차계약서, 전입세대열람원', NULL, NULL, 'https://www.bokjiro.go.kr'),
('MOCK-P006', '국민내일배움카드', '취업준비생 및 이직 희망 청년이 스스로 직업 능력을 개발하도록 평생교육 배움 비용을 보조합니다.', '교육', NULL, NULL, '2025-12-31', '5년간 300만원에서 최대 500만원까지의 훈련 직무 수강 비용 45~85% 지원', '일반 직장인, 미취업 청년, 졸업 예정 대학생 등 누구나 발급 가능', 'HRD-Net 또는 고용센터 방문을 통한 카드 발급 신청', NULL, NULL, '공무원, 사립학교 교직원, 연 매출 1억 5천만원 이상 자영업자 등은 제외', 'https://www.hrd.go.kr'),
('MOCK-P007', '서울시 청년수당', '서울 거주 미취업 청년들의 안정적인 구직활동과 진로 개척을 돕기 위해 생계 보조 청년 수당을 지급합니다.', '복지·문화', 19, 34, '2025-09-30', '월 50만원씩 최대 6개월간 매월 체크카드 바우처 포인트 형태로 지원금 지급', '서울 거주 만 19세~34세 졸업 후 미취업자 중 중위소득 150% 이하', '청년몽땅정보통 홈페이지에서 온라인 신청', '졸업증명서, 소득금액증명원, 구직활동계획서', '자격요건 서류 심사 후 예산 범위 내 선발', '구직촉진수당 등 유사 목적의 정부 지원사업과 중복 수급 불가', 'https://youth.seoul.go.kr'),
('MOCK-P008', '청년내일저축계좌', '일하는 청년들이 주거, 취업 등으로 인한 자립 기반을 갖출 수 있도록 정부가 목돈을 함께 마련해 줍니다.', '복지·문화', 19, 34, '2025-10-15', '본인 저축 월 10만원당 정부 지원금 10만~30만원을 3년간 1:1 매칭 적립', '일하고 있는 만 19세~34세 이하 청년 중 소득기준 충족자', '복지로 온라인 신청 또는 주소지 관할 행정복지센터 방문 신청', '재직증명서 또는 사업자등록증, 소득금액증명원, 통장사본', NULL, '가입 기간 중 3년 내 근로·사업활동을 지속하지 않으면 지급 제한', 'https://www.bokjiro.go.kr'),
('MOCK-P009', '청년문화예술패스', '사회에 첫 발을 내딛는 청년들에게 다채로운 문화생활과 연극, 전시, 음악 관람 비용을 전폭적으로 제공합니다.', '복지·문화', 19, 19, '2025-11-30', '공연 및 전시 관람료로 사용할 수 있는 포인트 최대 15만원 즉시 지급', '만 19세가 되는 국내 거주 모든 청년 (선착순 신청)', '청년문화예술패스 홈페이지 또는 앱에서 회원가입 후 신청', NULL, NULL, NULL, 'https://www.kopis.or.kr'),
('MOCK-P010', '정부부처 청년인턴', '중앙 행정 기관의 입법, 사업 진행 등의 부처 행정 실무를 인턴십으로 체험하고 참관할 기회를 제공합니다.', '참여·권리', 19, 34, '2025-06-15', '국가 공공 기관 인턴 근무 경력 증명서 발급 및 월 고정 기본급 및 수당 지급', '만 19세 이상 34세 이하의 미취업자 (학력 제한 없음)', '나라일터(잡알리오) 채용 공고를 통한 온라인 접수', '이력서, 자기소개서, 최종학력 증명서', '서류 전형 및 면접 전형', NULL, 'https://www.jobis.or.kr'),
('MOCK-P011', '청년 창업 지원금', '예비 창업자 및 창업 3년 이내 청년에게 사업화 자금과 멘토링을 함께 지원하는 사업입니다.', '일자리', 19, 39, '2025-08-20', '사업화 자금 최대 5천만원 및 전담 멘토 1:1 컨설팅 제공', '만 19세 이상 39세 이하 예비 창업자 및 창업 3년 이내 대표', 'K-스타트업 홈페이지에서 온라인 접수', '사업계획서, 사업자등록증 사본(창업자), 대표자 신분증 사본', '사업계획서 서류 심사 및 발표 평가', '동일 사업 기수 내 중복 선정 불가', 'https://www.k-startup.go.kr'),
('MOCK-P012', '청년 대중교통비 지원 (K-패스)', '월 15회 이상 대중교통을 이용하는 청년에게 지출 금액 일부를 다음 달에 환급해 줍니다.', '복지·문화', 19, 34, '2025-12-31', '월 대중교통 지출액의 30%를 익월 환급 (최대 60회 한도)', '만 19세 이상 34세 이하 K-패스 카드 발급자', 'K-패스 앱 또는 카드사 홈페이지에서 청년 등급 등록', NULL, NULL, NULL, 'https://korea-pass.kr'),
('MOCK-P013', '청년 전세자금 대출 이자 지원', '무주택 청년의 전세자금 대출 이자 부담을 낮춰 안정적인 주거 마련을 지원합니다.', '주거', 19, 39, '2025-09-30', '전세자금 대출 이자의 연 최대 2%p 차액 보전', '경기도 거주 무주택 미혼 청년 중 소득 기준 충족자', '경기도 청년포털에서 온라인 신청', '임대차계약서, 전세자금 대출 실행 확인서, 소득금액증명원', NULL, NULL, 'https://www.gg.go.kr'),
('MOCK-P014', '청년 정책참여단 모집', '청년 정책 기획 단계부터 직접 참여해 의견을 제안하고 정책 모니터링 활동을 수행합니다.', '참여·권리', 19, 34, '2025-07-31', '활동비 지급 및 정책 제안 채택 시 인센티브 제공', '만 19세 이상 34세 이하 청년 누구나 지원 가능', '청년정책 통합 플랫폼에서 온라인 신청', NULL, '지원서 심사 후 선발', '월 1회 정기 회의 2회 이상 불참 시 활동 중단', 'https://youth.go.kr');
